#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int add_modulo(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    return x;
}

int multiply_modulo(int x, int y) {
    long long res = 1LL * x * y;
    if (res >= MOD) res %= MOD;
    return (int)res;
}

int subtract_modulo(int x, int y) {
    x -= y;
    if (x < 0) x += MOD;
    return x;
}

int pow_modulo(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = multiply_modulo(res, base);
        base = multiply_modulo(base, base);
        exp >>= 1;
    }
    return res;
}

int get_lowbit_value(int x) {
    return x & (-x);
}

int n, a[10][10], ch[70010][128], cnt=0, qarr[10][128], dparr[10][70010];
unordered_map<bitset<128>, int> id_map;

int dfs_bitset(bitset<128> s) {
    if (id_map.count(s)) return id_map[s];
    id_map[s] = ++cnt;
    for (int i=0; i<(1<<n); i++) {
        bitset<128> tmp = s;
        for (int j=0; j<(1<<n); j++) {
            if (!tmp[j]) {
                int x = i & j;
                while (x) {
                    int t = get_lowbit_value(x);
                    if (s[j ^ t]) {
                        tmp[j] = 1;
                        break;
                    }
                    x -= t;
                }
            }
        }
        ch[id_map[s]][i] = dfs_bitset(tmp);
    }
    return id_map[s];
}

int main() {
    scanf("%d", &n);
    dfs_bitset(1);
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            scanf("%d", &a[i][j]);
            a[i][j] = multiply_modulo(a[i][j], pow_modulo(100, MOD - 2));
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<(1<<n); j++) {
            qarr[i][j] = 1;
            for (int k=0; k<n; k++) {
                if ((j>>k)&1) qarr[i][j] = multiply_modulo(qarr[i][j], a[i][k]);
                else qarr[i][j] = multiply_modulo(qarr[i][j], subtract_modulo(1, a[i][k]));
            }
        }
    }
    dparr[0][1] = 1;
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=cnt; j++) {
            for (int k=0; k<(1<<n); k++) {
                dparr[i][ch[j][k]] = add_modulo(dparr[i][ch[j][k]], multiply_modulo(dparr[i-1][j], qarr[i-1][k]));
            }
        }
    }
    bitset<128> bits;
    for (int i=0; i<(1<<n); i++) bits[i] = 1;
    printf("%d\n", dparr[n][id_map[bits]]);
    return 0;
}
